import{_ as a,o as i,c as t,a0 as l}from"./chunks/framework.Bmhw_dvp.js";const _=JSON.parse('{"title":"Page 30","description":"","frontmatter":{},"headers":[],"relativePath":"page-30.md","filePath":"page-30.md"}'),o={name:"page-30.md"};function d(c,e,r,s,n,p){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="page-30" tabindex="-1">Page 30 <a class="header-anchor" href="#page-30" aria-label="Permalink to &quot;Page 30&quot;">​</a></h1><h3 id="最短路算法-spfa-算法" tabindex="-1">最短路算法 - SPFA 算法 <a class="header-anchor" href="#最短路算法-spfa-算法" aria-label="Permalink to &quot;最短路算法 - SPFA 算法&quot;">​</a></h3><h4 id="四、spfa-算法" tabindex="-1">四、SPFA 算法 <a class="header-anchor" href="#四、spfa-算法" aria-label="Permalink to &quot;四、SPFA 算法&quot;">​</a></h4><ul><li><p>SPFA 算法在 Bellman-Ford 的基础上进行了优化，三角不等式 <code>dist[v] = min(dist[v], dist[u] + w)</code>。</p></li><li><p>在 SPFA 中，只有 <code>dist[u]</code> 变小了，后继的节点才可能更新。</p></li><li><p><strong>利用队列进行优化</strong>：</p><ul><li>起点加入队列，当队列非空：</li><li>① 取出队头 u，队头出队。</li><li>② 遍历 u 的所有出边 <code>u → v</code>，若更新成功，且 v 不在队列中，则入队。</li></ul></li><li><p>队列中存储待更新的节点。</p></li><li><ul><li>SPFA 算法也可替代 Dijkstra 算法，但若遇到网格图，SPFA 算法可能退化为 <code>O(nm)</code> 极慢，但一般快于 Dijkstra 算法。</li></ul></li><li><p><strong>SPFA 判负环思路</strong>：定义 <code>dist[i]</code> 表示最短距离，<code>cnt[i]</code> 表示最短路边数，在松弛时 <code>cnt[v] = cnt[u] + 1</code>。</p></li><li><p>若 <code>cnt[v] &gt; n</code>，则该路径出现负环，则存在负环。</p></li><li><p>由于判断的是整个图，故需将所有点入队。</p></li><li><p><strong>dist 初始化为 0 的原因</strong>：由于是判断负环，我们只需要找是否存在能持续更新的环，比较的是差的变化，而非距离值本身。</p></li><li><p>在判负环的实际问题中，<code>dist</code> 初始化为 0 比初始化为 <code>INF</code> 更高效（因为只需找环的差值）。</p></li></ul>',4)])])}const P=a(o,[["render",d]]);export{_ as __pageData,P as default};
